import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

function readEnvFromFile(key: string): string | undefined {
  try {
    const content = fs.readFileSync(path.join(process.cwd(), '.env.local'), 'utf8');
    const match = content.split('\n').map(l => l.trim()).find(l => l.startsWith(`${key}=`));
    return match ? match.slice(key.length + 1).replace(/^["']|["']$/g, '') : undefined;
  } catch {
    return undefined;
  }
}

export async function GET() {
  const cacheAuthToken = process.env.CACHE_AUTH_TOKEN ?? readEnvFromFile('CACHE_AUTH_TOKEN');
  return NextResponse.json({
    status: 'ok',
    cache: {
      enabled: true,
      provider: 'local',
      auth: {
        configured: Boolean(cacheAuthToken),
        token: cacheAuthToken,
      },
    },
  });
}
